xhtml:head.xhtml:script:
(function () {
  const XHTML_NS = "http://www.w3.org/1999/xhtml";
  const root = document.querySelector("foreignObject").firstElementChild;

  const originalCreateElement =
    document.createElement.bind(document);

  const originalCreateElementNS =
    document.createElementNS.bind(document);

  Object.defineProperty(document, "head", {
    get: () => root.querySelector("head"),
    configurable: true
  });

  Object.defineProperty(document, "body", {
    get: () => root.querySelector("body"),
    configurable: true
  });

  Object.defineProperty(document, "documentElement", {
    get: () => root,
    configurable: true
  });

  document.createElement = function (tagName, options) {
    if (typeof tagName === "string") {
      return originalCreateElementNS(XHTML_NS, tagName, options);
    }
    return originalCreateElement(tagName, options);
  };

  document.createElementNS = function (
    namespaceURI,
    qualifiedName,
    options
  ) {
    if (!namespaceURI || namespaceURI === XHTML_NS) {
      return originalCreateElementNS(
        XHTML_NS,
        qualifiedName,
        options
      );
    }

    return originalCreateElementNS(
      namespaceURI,
      qualifiedName,
      options
    );
  };
})();

xhtml:body.xhtml:script:
async function openProject() {
  const url =
    "https://raw.githubusercontent.com/pulse4web/chudsquad/refs/heads/main/index.html";

  const response = await fetch(url);
  const html = await response.text();

  const tab = window.open("about:blank", "_blank");

  if (!tab) {
    alert("Please allow pop-ups for this page.");
    return;
  }

  const iframe = tab.document.createElement("iframe");

  iframe.style.cssText =
    "position:fixed;inset:0;width:100%;height:100%;border:0";

  iframe.srcdoc = html;

  tab.document.body.style.margin = "0";
  tab.document.body.appendChild(iframe);
}
